3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	
6	public enum FormaPagamento {
7	
8	    PIX {
9	        @Override
10	        public boolean parcelamentoValido(int parcelas) {
11	            return parcelas == 1;
12	        }
13	
14	        @Override
15	        public ResultadoPagamento calcular(BigDecimal total, int parcelas) {
16	            BigDecimal desconto = total.multiply(new BigDecimal("0.05")).setScale(2, RoundingMode.HALF_EVEN);
17	            BigDecimal totalFinal = total.subtract(desconto);
18	            return new ResultadoPagamento(totalFinal, totalFinal, 1);
19	        }
20	
21	        @Override
22	        public boolean disponivel(BigDecimal total) {
23	            return true;
24	        }
25	    },
26	
27	    CARTAO {
28	        @Override
29	        public boolean parcelamentoValido(int parcelas) {
30	            return parcelas >= 1 && parcelas <= 12;
31	        }
32	
33	        @Override
34	        public ResultadoPagamento calcular(BigDecimal total, int parcelas) {
35	            if (parcelas <= 3) {
36	                BigDecimal valorParcela = total.divide(BigDecimal.valueOf(parcelas), 2, RoundingMode.HALF_EVEN);
37	                return new ResultadoPagamento(total, valorParcela, parcelas);
38	            }
39	            BigDecimal taxa = new BigDecimal("0.0199");
40	            BigDecimal umMaisTaxa = BigDecimal.ONE.add(taxa);
41	            BigDecimal potencia = BigDecimal.ONE;
42	            for (int i = 0; i < parcelas; i++) {
43	                potencia = potencia.multiply(umMaisTaxa);
44	            }
45	            BigDecimal inverso = BigDecimal.ONE.divide(potencia, 20, RoundingMode.HALF_EVEN);
46	            BigDecimal denominador = BigDecimal.ONE.subtract(inverso);
47	            BigDecimal valorParcela = total.multiply(taxa).divide(denominador, 2, RoundingMode.HALF_EVEN);
48	            BigDecimal totalFinal = valorParcela.multiply(BigDecimal.valueOf(parcelas));
49	            return new ResultadoPagamento(totalFinal, valorParcela, parcelas);
50	        }
51	
52	        @Override
53	        public boolean disponivel(BigDecimal total) {
54	            return true;
55	        }
56	    },
57	
58	    BOLETO {
59	        @Override
60	        public boolean parcelamentoValido(int parcelas) {
61	            return parcelas == 1;
62	        }
63	
64	        @Override
65	        public ResultadoPagamento calcular(BigDecimal total, int parcelas) {
66	            BigDecimal totalFinal = total.add(new BigDecimal("3.49"));
67	            return new ResultadoPagamento(totalFinal, totalFinal, 1);
68	        }
69	
70	        @Override
71	        public boolean disponivel(BigDecimal total) {
72	            return total.compareTo(new BigDecimal("1000.00")) <= 0;
73	        }
74	    };
75	
