1	package com.loja.checkout.service;
2	
3	import com.loja.checkout.exception.CheckoutException;
4	import com.loja.checkout.model.*;
5	import org.springframework.stereotype.Service;
6	
7	import java.math.BigDecimal;
8	import java.math.RoundingMode;
9	import java.util.List;
10	
11	@Service
12	public class CheckoutService {
13	
14	    public ResumoResponse calcular(PedidoRequest pedido) {
15	        validarItens(pedido.itens());
16	
17	        NivelClube nivel = parsarEnum(NivelClube.class, pedido.nivelClube(), "NIVEL_CLUBE_INVALIDO");
18	        Regiao regiao = parsarEnum(Regiao.class, pedido.regiao(), "REGIAO_INVALIDA");
19	        ModalidadeEntrega modalidade = parsarEnum(ModalidadeEntrega.class, pedido.modalidadeEntrega(), "MODALIDADE_INVALIDA");
20	
21	        BigDecimal pesoTotal = calcularPesoTotal(pedido.itens());
22	        if (!modalidade.disponivel(pesoTotal)) {
23	            throw new CheckoutException("MODALIDADE_INDISPONIVEL");
24	        }
25	
26	        BigDecimal subtotal = calcularSubtotal(pedido.itens());
27	
28	        Cupom cupom = parsarCupom(pedido.cupom());
29	        if (cupom != null && !cupom.aplicavel(subtotal, pedido.itens())) {
30	            throw new CheckoutException("CUPOM_NAO_APLICAVEL");
31	        }
32	
33	        FormaPagamento pagamento = parsarEnum(FormaPagamento.class, pedido.formaPagamento(), "FORMA_PAGAMENTO_INVALIDA");
34	        int parcelas = pedido.parcelas() != null ? pedido.parcelas() : 1;
35	        if (!pagamento.parcelamentoValido(parcelas)) {
36	            throw new CheckoutException("PARCELAMENTO_INVALIDO");
37	        }
38	
39	        BigDecimal frete = modalidade.calcularFrete(pesoTotal);
40	        if (nivel.freteGratis()) {
41	            frete = BigDecimal.ZERO.setScale(2);
42	        }
43	
44	        BigDecimal descontoCupom = BigDecimal.ZERO.setScale(2);
45	        if (cupom != null) {
46	            descontoCupom = cupom.calcularDesconto(subtotal, pedido.itens(), frete);
47	        }
48	
49	        BigDecimal seguro = regiao.calcularSeguro(subtotal);
50	
51	        BigDecimal totalPedido = subtotal.subtract(descontoCupom).add(frete).add(seguro);
52	
53	        if (!pagamento.disponivel(totalPedido)) {
54	            throw new CheckoutException("FORMA_PAGAMENTO_INDISPONIVEL");
55	        }
56	
57	        ResultadoPagamento resultado = pagamento.calcular(totalPedido, parcelas);
58	        BigDecimal ajuste = resultado.totalFinal().subtract(totalPedido).setScale(2, RoundingMode.HALF_EVEN);
59	
60	        BigDecimal credito = nivel.calcularCredito(subtotal);
61	        boolean brinde = nivel.temBrinde(subtotal);
62	
63	        return new ResumoResponse(
64	                subtotal, descontoCupom, frete, modalidade.prazoDias(), seguro,
65	                ajuste, resultado.totalFinal(), parcelas, resultado.valorParcela(),
66	                credito, brinde);
67	    }
68	
69	    private void validarItens(List<ItemPedido> itens) {
70	        if (itens == null || itens.isEmpty()) {
71	            throw new CheckoutException("PEDIDO_INVALIDO");
72	        }
73	        for (ItemPedido item : itens) {
74	            if (item.precoUnitario() == null || item.precoUnitario().compareTo(BigDecimal.ZERO) <= 0
75	                    || item.quantidade() == null || item.quantidade() <= 0
76	                    || item.pesoKg() == null || item.pesoKg().compareTo(BigDecimal.ZERO) <= 0) {
77	                throw new CheckoutException("PEDIDO_INVALIDO");
78	            }
79	        }
80	    }
81	
82	    private BigDecimal calcularSubtotal(List<ItemPedido> itens) {
83	        BigDecimal subtotal = BigDecimal.ZERO;
84	        for (ItemPedido item : itens) {
85	            subtotal = subtotal.add(item.precoUnitario().multiply(BigDecimal.valueOf(item.quantidade())));
86	        }
87	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
88	    }
89	
90	    private BigDecimal calcularPesoTotal(List<ItemPedido> itens) {
91	        BigDecimal peso = BigDecimal.ZERO;
92	        for (ItemPedido item : itens) {
93	            peso = peso.add(item.pesoKg().multiply(BigDecimal.valueOf(item.quantidade())));
94	        }
95	        return peso;
96	    }
97	
98	    private Cupom parsarCupom(String codigo) {
99	        if (codigo == null || codigo.isBlank()) {
100	            return null;
101	        }
102	        try {
103	            return Cupom.valueOf(codigo);
104	        } catch (IllegalArgumentException e) {
105	            throw new CheckoutException("CUPOM_INVALIDO");
106	        }
107	    }
108	
109	    private <E extends Enum<E>> E parsarEnum(Class<E> tipo, String valor, String codigoErro) {
110	        if (valor == null || valor.isBlank()) {
111	            throw new CheckoutException(codigoErro);
112	        }
113	        try {
114	            return Enum.valueOf(tipo, valor);
115	        } catch (IllegalArgumentException e) {
116	            throw new CheckoutException(codigoErro);
117	        }
118	    }
119	}
